insert into public.destinations (slug, name, country, region, description, cover_src, cover_alt, cover_width, cover_height, cover_color, lat, lng, is_sample, sort_order) values
  ('alps', 'The Alps', 'Switzerland & Italy', null, 'High snow, cloud seas below the ridgeline and lakes the colour of sea glass.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=max&w=2000&q=80', 'Jagged snow peaks rising above a sea of cloud at sunrise, the sky fading from pink to blue', 2000, 1333, '#706f7b', null, null, true, 1),
  ('japan', 'Japan', 'Japan', null, 'Wooden lanes at dusk, red pagodas, and one mountain that keeps showing up.', 'https://images.unsplash.com/photo-1526481280693-3bfa7568e0f3?auto=format&fit=max&w=2000&q=80', 'A red five-storey pagoda in a green hillside with Mount Fuji rising over the town beyond', 2000, 1333, '#647984', null, null, true, 2),
  ('india', 'India', 'India', null, 'Marble at dawn, yellow taxis at night, and streets that never quite empty.', 'https://images.unsplash.com/photo-1524492412937-b28074a5d7da?auto=format&fit=max&w=2000&q=80', 'The Taj Mahal at dawn, mirrored in a long reflecting pool lined with clipped cypresses', 2000, 1333, '#8a9196', null, null, true, 3),
  ('indonesia', 'Indonesia', 'Indonesia', null, 'Temples in mist, on lakes and on hilltops, from Bali to Java.', 'https://images.unsplash.com/photo-1596402184320-417e7178b2cd?auto=format&fit=max&w=2000&q=80', 'Bell-shaped stupas rising through morning haze at Borobudur', 2000, 1333, '#826251', null, null, true, 4),
  ('paris', 'Paris', 'France', 'Île-de-France', 'The river at dusk, gilded lamps coming on, and a skyline you already know.', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=max&w=2000&q=80', 'The Eiffel Tower against a lilac dusk sky with the river in the foreground', 2000, 1333, '#817c88', 48.857, 2.352, true, 5)
insert into public.trips (slug, title, summary, story, cover_src, cover_alt, cover_width, cover_height, cover_color, destination_slug, start_date, end_date, period_label, is_sample, featured, sort_order) values
  ('alpine-light', 'Alpine Light', 'Cloud seas at sunrise, turquoise lakes and a long blue hour in the high country.', 'The mountains do most of the work here. Light arrives from the side, catches one ridge at a time, and leaves the valleys in blue shadow.
