  ('greenhouse-corner', 'Greenhouse Corner', null, null, 'By the glass wall', null, 'https://images.unsplash.com/photo-1445116572660-236099ec97a0?auto=format&fit=max&w=2000&q=80', 'A round café table with a French press by a glass wall dripping with greenery', 2000, 1333, '#747368', array['plants', 'window seat', 'slow morning']::text[], 'Sample entry. A café where the garden presses against the glass and nobody minds how long you stay.', 'French press', true, 1),
  ('bicycle-room', 'The Bicycle Room', null, null, 'Concrete and pendant bulbs', null, 'https://images.unsplash.com/photo-1493857671505-72967e2e2760?auto=format&fit=max&w=2000&q=80', 'A concrete-walled café with a menu board and two bicycles leaning inside', 2000, 1333, '#796f5b', array['industrial', 'bikes', 'bright']::text[], 'Sample entry. Raw concrete, a long counter and a couple of bicycles that live inside.', 'Cortado', true, 2),
  ('slow-pour', 'Slow Pour', null, null, 'Brew bar', null, 'https://images.unsplash.com/photo-1442512595331-e89e73853f31?auto=format&fit=max&w=2000&q=80', 'A barista pouring from a gooseneck kettle over a pour-over dripper, glassware behind', 2000, 1333, '#3f4645', array['pour-over', 'filter', 'beans']::text[], 'Sample entry. A bar that treats filter coffee as a small ceremony.', 'Pour-over', true, 3),
