insert into public.stories (slug, title, subtitle, published_at, reading_time_minutes, excerpt, body, cover_src, cover_alt, cover_width, cover_height, cover_color, trip_slug, destination_slug, is_sample, featured, sort_order) values
  ('reading-the-light-in-the-alps', 'Reading the light in the Alps', 'Sunrise, lake and stars in one mountain day', null, 3, 'Mountains are patient subjects. The light is what moves, and the trick is knowing where to stand when it does.', 'Mountains are patient subjects. The light is what moves, and the trick is knowing where to stand when it does.
insert into public.postcards (slug, title, caption, note, image_src, image_alt, image_width, image_height, image_color, category, place_name, city, region, country, lat, lng, taken_on, period_label, trip_slug, destination_slug, cafe_slug, story_slug, tags, camera, credit, credit_url, is_sample, featured, sort_order) values
  ('above-the-clouds', 'Above the clouds', 'A cloud sea filling the valley below the high peaks.', 'Wake early. The valley is worth it.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=max&w=2000&q=80', 'Jagged snow peaks rising above a sea of cloud at sunrise, the sky fading from pink to blue', 2000, 1333, '#706f7b', 'travel', 'Valais', null, 'Valais', 'Switzerland', null, null, null, null, 'alpine-light', 'alps', null, null, array['alps', 'sunrise', 'mountains']::text[], null, 'Unsplash', 'https://unsplash.com', true, true, 1),
  ('braies-turquoise', 'Turquoise at Braies', 'Green-blue water, a lone rowboat, limestone walls.', null, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=max&w=2000&q=80', 'A small wooden rowboat on turquoise alpine water with limestone peaks behind', 2000, 1333, '#6c938f', 'travel', 'Lago di Braies', null, 'Dolomites', 'Italy', 46.694, 12.086, null, null, 'alpine-light', 'alps', null, null, array['alps', 'lake', 'water']::text[], null, 'Unsplash', 'https://unsplash.com', true, true, 2),
  ('braies-rowboat', 'Bow on the lake', 'The boat''s nose points at the far shore.', null, 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=max&w=2000&q=80', 'The bow of a wooden rowboat pointing across a green mountain lake toward grey peaks', 2000, 1333, '#737569', 'travel', 'Lago di Braies', null, 'Dolomites', 'Italy', 46.694, 12.086, null, null, 'alpine-light', 'alps', null, null, array['alps', 'lake', 'boat']::text[], null, 'Unsplash', 'https://unsplash.com', true, false, 3),
