  ('fuji-pagoda', 'Pagoda and the mountain', 'A red pagoda on the hill, Fuji standing over the town.', null, 'https://images.unsplash.com/photo-1526481280693-3bfa7568e0f3?auto=format&fit=max&w=2000&q=80', 'A red five-storey pagoda in a green hillside with Mount Fuji rising over the town beyond', 2000, 1333, '#647984', 'travel', 'Chureito Pagoda', 'Fujiyoshida', null, 'Japan', 35.502, 138.801, null, null, 'paper-lanterns', 'japan', null, null, array['japan', 'pagoda', 'mountain']::text[], null, 'Unsplash', 'https://unsplash.com', true, true, 5),
  ('taj-reflection', 'Long reflection', 'The pool doubles the dome in the first light.', null, 'https://images.unsplash.com/photo-1524492412937-b28074a5d7da?auto=format&fit=max&w=2000&q=80', 'The Taj Mahal at dawn, mirrored in a long reflecting pool lined with clipped cypresses', 2000, 1333, '#8a9196', 'travel', 'Taj Mahal', 'Agra', null, 'India', 27.175, 78.042, null, null, 'subcontinent-days', 'india', null, null, array['india', 'monument', 'dawn']::text[], null, 'Unsplash', 'https://unsplash.com', true, false, 6),
